import { useEffect, useRef } from 'react';
import { ArrowUpRight } from 'lucide-react';
import { useTranslation } from 'react-i18next';
import gsap from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';
import { whatsappMessageHref } from '@/lib/whatsapp';
import { trackCta } from '@/lib/tracking';

gsap.registerPlugin(ScrollTrigger);

export default function Consulting() {
  const ref = useRef<HTMLElement>(null);
  const { t } = useTranslation();

  useEffect(() => {
    const s = ref.current;
    if (!s) return;
    const ctx = gsap.context(() => {
      gsap.fromTo(s.querySelectorAll('.c-item'), { opacity: 0, y: 30 }, {
        opacity: 1, y: 0, duration: 0.7, stagger: 0.12, ease: 'power3.out',
        scrollTrigger: { trigger: s, start: 'top 85%' },
      });
    }, s);
    return () => ctx.revert();
  }, []);

  const waLink = whatsappMessageHref(t('whatsapp.consultLead'));

  return (
    <section ref={ref} id="cta-final" className="layout-section w-full">
      <div className="container mx-auto max-w-2xl text-center">
        <p className="c-item eyebrow mb-6 opacity-0">{t('consulting.eyebrow')}</p>
        <h2 className="c-item text-foreground font-bold mb-4 opacity-0 text-balance" style={{ fontSize: 'var(--text-section)', lineHeight: 'var(--leading-tight)' }}>
          {t('consulting.title')}
        </h2>
        <p className="c-item text-muted-foreground mb-8 max-w-xl mx-auto opacity-0 leading-[1.65]" style={{ fontSize: 'var(--text-body)' }}>
          {t('consulting.subtitle')}
        </p>
        <a
          href={waLink}
          target="_blank"
          rel="noopener noreferrer"
          onClick={() => trackCta('cta_consulting_whatsapp', { source: 'consulting' })}
          className="c-item group inline-flex items-center gap-2 bg-primary text-primary-foreground text-sm font-semibold px-6 py-3 rounded-full hover:opacity-90 transition-opacity opacity-0"
        >
          <span>{t('consulting.cta')}</span>
          <ArrowUpRight size={14} className="transition-transform group-hover:translate-x-0.5 group-hover:-translate-y-0.5" />
        </a>
      </div>
    </section>
  );
}
