import { useEffect, useMemo } from 'react';
import { Link, useParams } from 'react-router';
import { useTranslation } from 'react-i18next';
import { format, parseISO } from 'date-fns';
import { enUS, ptBR, ru } from 'date-fns/locale';
import { ArrowUpRight } from 'lucide-react';
import { CaseInternoHeader } from '@/components/CaseInternoHeader';
import { estimateReadingMinutes, getCaseContent, getCaseRecord } from '@/data/casesInterno';
import { whatsappMessageHref } from '@/lib/whatsapp';
import { cn } from '@/lib/utils';

function dateLocale(code: string) {
  if (code.startsWith('pt')) return ptBR;
  if (code.startsWith('ru')) return ru;
  return enUS;
}

const tocIds = {
  resumo: 'ci-resumo',
  contexto: 'ci-contexto',
  desafio: 'ci-desafio',
  abordagem: 'ci-abordagem',
  solucao: 'ci-solucao',
  resultados: 'ci-resultados',
  stack: 'ci-stack',
  links: 'ci-links',
  leituras: 'ci-leituras',
} as const;

export default function CaseInternoDetailPage() {
  const { slug } = useParams<{ slug: string }>();
  const { t, i18n } = useTranslation();
  const loc = dateLocale(i18n.language);

  const record = slug ? getCaseRecord(slug) : null;
  const c = slug ? getCaseContent(slug, i18n.language) : null;
  const minutes = c ? estimateReadingMinutes(c) : 0;

  const publishedLabel = useMemo(() => {
    if (!c?.publishedAt) return null;
    try {
      return format(parseISO(c.publishedAt), 'PP', { locale: loc });
    } catch {
      return c.publishedAt;
    }
  }, [c?.publishedAt, loc]);

  useEffect(() => {
    if (!c || !slug) return;
    document.title = `${c.title}${t('caseInternoPage.metaDetailSuffix')}`;
    const jsonLd = {
      '@context': 'https://schema.org',
      '@type': 'TechArticle',
      headline: c.title,
      description: c.dek,
      datePublished: c.publishedAt,
      author: { '@type': 'Person', name: 'Mauro Silva' },
      about: c.category,
    };
    const el = document.createElement('script');
    el.type = 'application/ld+json';
    el.setAttribute('data-caseinterno-ld', '1');
    el.textContent = JSON.stringify(jsonLd);
    document.head.appendChild(el);
    return () => {
      document.head.querySelectorAll('script[data-caseinterno-ld]').forEach((n) => n.remove());
    };
  }, [c, slug, t]);

  if (!slug || !record || !c) {
    return (
      <div className="min-h-screen bg-background text-foreground">
        <CaseInternoHeader backTo="/caseinterno" backLabel={t('caseInternoPage.backIndex')} />
        <main className="container py-16 md:py-24">
          <h1 className="text-2xl font-semibold">{t('caseInternoPage.notFoundTitle')}</h1>
          <p className="mt-3 max-w-md text-muted-foreground">{t('caseInternoPage.notFoundBody')}</p>
          <Link to="/caseinterno" className="mt-8 inline-flex text-sm font-medium text-foreground underline underline-offset-4">
            {t('caseInternoPage.backIndex')}
          </Link>
        </main>
      </div>
    );
  }

  const wa = whatsappMessageHref(t('whatsapp.defaultLead'));

  const toc = [
    { id: tocIds.resumo, label: t('caseInternoPage.execSummary') },
    { id: tocIds.contexto, label: t('caseInternoPage.context') },
    { id: tocIds.desafio, label: t('caseInternoPage.challenge') },
    { id: tocIds.abordagem, label: t('caseInternoPage.approach') },
    { id: tocIds.solucao, label: t('caseInternoPage.solution') },
    ...(c.outcomes?.length ? [{ id: tocIds.resultados, label: t('caseInternoPage.outcomes') }] : []),
    { id: tocIds.stack, label: t('caseInternoPage.stack') },
    { id: tocIds.links, label: t('caseInternoPage.resources') },
    ...(c.reading?.length ? [{ id: tocIds.leituras, label: t('caseInternoPage.readingList') }] : []),
  ];

  return (
    <div className="min-h-screen bg-background text-foreground transition-colors duration-300">
      <CaseInternoHeader backTo="/caseinterno" backLabel={t('caseInternoPage.backIndex')} />

      <main className="container py-8 md:py-12">
        {record.heroImage ? (
          <div className="mb-10 overflow-hidden rounded-2xl border border-border bg-secondary/30 dark:bg-white/[0.04]">
            <img src={record.heroImage} alt="" className="aspect-[21/9] w-full object-cover md:aspect-[24/9]" />
          </div>
        ) : null}

        <div className="mx-auto flex max-w-6xl flex-col gap-10 lg:flex-row lg:gap-16">
          <article className="min-w-0 flex-1">
            <div className="mb-6 flex flex-wrap items-center gap-2">
              <span className="rounded-full border border-border px-3 py-1 text-xs font-semibold uppercase tracking-wide text-muted-foreground">
                {c.category}
              </span>
              {c.confidential ? (
                <span className="rounded-full border border-amber-500/40 bg-amber-500/10 px-3 py-1 text-xs font-semibold text-amber-800 dark:text-amber-200">
                  {t('caseInternoPage.confidential')}
                </span>
              ) : null}
            </div>

            <h1 className="text-balance text-3xl font-semibold tracking-tight md:text-4xl">{c.title}</h1>
            <p className="mt-4 max-w-3xl text-base leading-relaxed text-muted-foreground md:text-lg">{c.dek}</p>

            <dl className="mt-8 flex flex-wrap gap-x-8 gap-y-3 text-sm">
              <div>
                <dt className="text-muted-foreground">{t('caseInternoPage.role')}</dt>
                <dd className="font-medium text-foreground">{c.role}</dd>
              </div>
              <div>
                <dt className="text-muted-foreground">{t('caseInternoPage.timeline')}</dt>
                <dd className="font-medium text-foreground">{c.timeline}</dd>
              </div>
              {publishedLabel ? (
                <div>
                  <dt className="text-muted-foreground">{t('caseInternoPage.published')}</dt>
                  <dd className="font-medium text-foreground">{publishedLabel}</dd>
                </div>
              ) : null}
              <div>
                <dt className="text-muted-foreground">{t('caseInternoPage.metaReading')}</dt>
                <dd className="font-medium text-foreground">{t('caseInternoPage.readingTime', { count: minutes })}</dd>
              </div>
            </dl>

            <section id={tocIds.resumo} className="scroll-mt-28 border-t border-border pt-10 mt-10">
              <h2 className="text-lg font-semibold">{t('caseInternoPage.execSummary')}</h2>
              <p className="mt-3 text-sm leading-relaxed text-muted-foreground md:text-base">{c.execSummary}</p>
            </section>

            <section id={tocIds.contexto} className="scroll-mt-28 border-t border-border pt-10 mt-10">
              <h2 className="text-lg font-semibold">{t('caseInternoPage.context')}</h2>
              <p className="mt-3 text-sm leading-relaxed text-muted-foreground md:text-base">{c.context}</p>
            </section>

            <section id={tocIds.desafio} className="scroll-mt-28 border-t border-border pt-10 mt-10">
              <h2 className="text-lg font-semibold">{t('caseInternoPage.challenge')}</h2>
              <p className="mt-3 text-sm leading-relaxed text-muted-foreground md:text-base">{c.challenge}</p>
            </section>

            <section id={tocIds.abordagem} className="scroll-mt-28 border-t border-border pt-10 mt-10">
              <h2 className="text-lg font-semibold">{t('caseInternoPage.approach')}</h2>
              <ul className="mt-4 list-disc space-y-2 pl-5 text-sm leading-relaxed text-muted-foreground md:text-base">
                {c.approach.map((item) => (
                  <li key={item}>{item}</li>
                ))}
              </ul>
            </section>

            <section id={tocIds.solucao} className="scroll-mt-28 border-t border-border pt-10 mt-10">
              <h2 className="text-lg font-semibold">{t('caseInternoPage.solution')}</h2>
              <p className="mt-3 text-sm leading-relaxed text-muted-foreground md:text-base">{c.solution}</p>
            </section>

            {c.outcomes?.length ? (
              <section id={tocIds.resultados} className="scroll-mt-28 border-t border-border pt-10 mt-10">
                <h2 className="text-lg font-semibold">{t('caseInternoPage.outcomes')}</h2>
                <ul className="mt-4 list-disc space-y-2 pl-5 text-sm leading-relaxed text-muted-foreground md:text-base">
                  {c.outcomes.map((item) => (
                    <li key={item}>{item}</li>
                  ))}
                </ul>
              </section>
            ) : null}

            <section id={tocIds.stack} className="scroll-mt-28 border-t border-border pt-10 mt-10">
              <h2 className="text-lg font-semibold">{t('caseInternoPage.stack')}</h2>
              <ul className="mt-4 flex flex-wrap gap-2">
                {c.stack.map((s) => (
                  <li
                    key={s}
                    className="rounded-full border border-border bg-secondary/50 px-3 py-1 text-xs font-medium text-foreground dark:bg-white/[0.06]"
                  >
                    {s}
                  </li>
                ))}
              </ul>
            </section>

            <section id={tocIds.links} className="scroll-mt-28 border-t border-border pt-10 mt-10">
              <h2 className="text-lg font-semibold">{t('caseInternoPage.resources')}</h2>
              <ul className="mt-4 space-y-2">
                {c.resources.map((r) => (
                  <li key={r.href}>
                    <a
                      href={r.href}
                      target="_blank"
                      rel="noopener noreferrer"
                      className="group inline-flex items-center gap-1.5 text-sm font-medium text-foreground underline-offset-4 hover:underline"
                    >
                      {r.label}
                      <ArrowUpRight size={14} className="opacity-60 transition-transform group-hover:translate-x-0.5 group-hover:-translate-y-0.5" />
                    </a>
                    {r.kind ? (
                      <span className="ml-2 text-xs uppercase tracking-wide text-muted-foreground">({r.kind})</span>
                    ) : null}
                  </li>
                ))}
              </ul>
            </section>

            {c.reading?.length ? (
              <section id={tocIds.leituras} className="scroll-mt-28 border-t border-border pt-10 mt-10">
                <h2 className="text-lg font-semibold">{t('caseInternoPage.readingList')}</h2>
                <ul className="mt-4 space-y-2">
                  {c.reading.map((r) => (
                    <li key={r.href}>
                      <a
                        href={r.href}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="group inline-flex items-center gap-1.5 text-sm text-muted-foreground underline-offset-4 hover:text-foreground hover:underline"
                      >
                        {r.label}
                        <ArrowUpRight size={14} className="opacity-60 transition-transform group-hover:translate-x-0.5 group-hover:-translate-y-0.5" />
                      </a>
                    </li>
                  ))}
                </ul>
              </section>
            ) : null}

            <div className="mt-14 rounded-2xl border border-border bg-secondary/30 p-6 dark:bg-white/[0.04] md:p-8">
              <p className="text-sm font-medium text-foreground">{t('caseInternoPage.ctaDiscuss')}</p>
              <a
                href={wa}
                target="_blank"
                rel="noopener noreferrer"
                className="mt-4 inline-flex items-center gap-2 rounded-full bg-foreground px-6 py-3 text-sm font-semibold text-background transition-opacity hover:opacity-90"
              >
                WhatsApp
                <ArrowUpRight size={14} />
              </a>
            </div>
          </article>

          <aside className="w-full shrink-0 lg:w-56">
            <nav
              className={cn(
                'rounded-2xl border border-border bg-card p-4 text-sm',
                'lg:sticky lg:top-28',
              )}
              aria-label={t('caseInternoPage.toc')}
            >
              <p className="mb-3 text-xs font-semibold uppercase tracking-wide text-muted-foreground">{t('caseInternoPage.toc')}</p>
              <ol className="space-y-2">
                {toc.map((item) => (
                  <li key={item.id}>
                    <a href={`#${item.id}`} className="text-muted-foreground transition-colors hover:text-foreground">
                      {item.label}
                    </a>
                  </li>
                ))}
              </ol>
            </nav>
          </aside>
        </div>
      </main>
    </div>
  );
}
