import { useEffect, useRef } from 'react';
import { ArrowUpRight } from 'lucide-react';
import { useTranslation } from 'react-i18next';
import gsap from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';
import { cn } from '@/lib/utils';
import { whatsappMessageHref } from '@/lib/whatsapp';

gsap.registerPlugin(ScrollTrigger);

type ClientLogo = {
  name: string;
  href: string;
  w: number;
  h: number;
  src?: string;
  text?: string;
};

const logos: ClientLogo[] = [
  {
    name: 'wayship',
    src: '/images/logo-wayship.png',
    href: 'https://wayship.com.br',
    w: 140,
    h: 48,
  },
  {
    name: 'mymailsign',
    src: '/images/mymailsign.png',
    href: 'https://mymailsign.com',
    w: 120,
    h: 34,
  },
  {
    name: 'tunnel',
    src: '/images/tunnel.avif',
    href: 'https://tunnel.ag',
    w: 120,
    h: 28,
  },
];

export default function ClientLogos() {
  const ref = useRef<HTMLElement>(null);
  const { t } = useTranslation();

  useEffect(() => {
    const s = ref.current;
    if (!s) return;
    const items = s.querySelectorAll('.logo-item');
    const risk = s.querySelector('.logo-risk-block');
    const ctx = gsap.context(() => {
      gsap.fromTo(items, { opacity: 0, y: 12 }, {
        opacity: 1, y: 0, duration: 0.5, stagger: 0.1, ease: 'power3.out',
        scrollTrigger: { trigger: s, start: 'top 85%' },
      });
      if (risk) {
        gsap.fromTo(risk, { opacity: 0, y: 16 }, {
          opacity: 1, y: 0, duration: 0.55, ease: 'power3.out', delay: 0.15,
          scrollTrigger: { trigger: s, start: 'top 85%' },
        });
      }
    }, s);
    return () => ctx.revert();
  }, []);

  return (
    <section ref={ref} className="layout-section w-full">
      <div className="container">
        <p className="eyebrow mb-12 text-center">{t('logos.eyebrow')}</p>
        <div className="mx-auto flex max-w-3xl flex-wrap items-stretch justify-center gap-4 sm:gap-5 md:gap-8">
          {logos.map((l) => (
            <a
              key={l.name}
              href={l.href}
              target="_blank"
              rel="noopener noreferrer"
              className={cn(
                'logo-item flex h-[5.25rem] w-[min(100%,11.5rem)] shrink-0 items-center justify-center sm:w-[12.5rem]',
                'rounded-2xl border border-border bg-secondary/40 px-6 py-4 md:px-8 md:py-5',
                'dark:bg-white/[0.04] opacity-0 transition-[border-color,box-shadow,transform] duration-300',
                'hover:border-foreground/12 hover:shadow-sm hover:shadow-black/5 dark:hover:border-white/10 dark:hover:shadow-white/5',
              )}
            >
              {l.src ? (
                <img
                  src={l.src}
                  alt={l.name}
                  width={l.w}
                  height={l.h}
                  className="h-7 w-auto max-h-8 object-contain brightness-0 dark:invert"
                  style={l.w ? { maxWidth: l.w } : undefined}
                />
              ) : (
                <span className="text-center text-base font-light tracking-[0.12em] text-foreground">{l.text ?? l.name}</span>
              )}
            </a>
          ))}
        </div>

        <div className="logo-risk-block mt-14 md:mt-20 max-w-xl mx-auto text-center border-t border-border pt-12 md:pt-14 opacity-0">
          <p
            className="text-foreground font-medium mb-6 text-balance"
            style={{ fontSize: 'clamp(1.0625rem, 2.2vw, 1.25rem)', lineHeight: 1.35 }}
          >
            {t('logos.deliveryRiskQuestion')}
          </p>
          <a
            href={whatsappMessageHref(t('whatsapp.urgentDelivery'))}
            target="_blank"
            rel="noopener noreferrer"
            className="group inline-flex max-w-[min(100%,22rem)] flex-wrap items-center justify-center gap-2 bg-foreground text-background text-sm font-semibold px-6 py-3.5 rounded-full text-center hover:opacity-[0.88] transition-opacity active:scale-[0.98] sm:max-w-none"
          >
            <span className="text-pretty text-balance">{t('logos.deliveryRiskCta')}</span>
            <ArrowUpRight size={14} className="transition-transform group-hover:translate-x-0.5 group-hover:-translate-y-0.5" />
          </a>
        </div>
      </div>
    </section>
  );
}
