import { useEffect, useMemo } from 'react';
import { Link } from 'react-router';
import { useTranslation } from 'react-i18next';
import { format } from 'date-fns';
import { enUS, ptBR, ru } from 'date-fns/locale';
import { ArrowLeft, ArrowUpRight, Moon, Sun } from 'lucide-react';
import { useTheme } from '@/hooks/useTheme';
import { nextPromoSprintStart } from '@/lib/nextPromoSprintStart';
import { whatsappMessageHref } from '@/lib/whatsapp';
import { trackCta } from '@/lib/tracking';
import { cn } from '@/lib/utils';

function dateLocale(code: string) {
  if (code.startsWith('pt')) return ptBR;
  if (code.startsWith('ru')) return ru;
  return enUS;
}

export default function ListaPage() {
  const { t, i18n } = useTranslation();
  const { theme, toggleTheme } = useTheme();
  const loc = dateLocale(i18n.language);

  const start = useMemo(() => nextPromoSprintStart(), []);
  const dateShort = format(start, 'dd/MM/yyyy', { locale: loc });

  useEffect(() => {
    document.title = t('listaPage.metaTitle');
    return () => {
      document.title = 'MAUROSILVASTUDIO · Studio de desenvolvimento para agências';
    };
  }, [t]);

  const waLista = whatsappMessageHref(t('whatsapp.listaWaitlist', { date: dateShort }));
  const bullets = t('listaPage.bullets', { returnObjects: true }) as string[];

  return (
    <div className="min-h-screen bg-background text-foreground transition-colors duration-300">
      <header className="border-b border-border">
        <div className="container flex h-14 items-center justify-between md:h-16">
          <Link
            to="/"
            className="inline-flex items-center gap-2 text-sm text-muted-foreground transition-colors hover:text-foreground"
          >
            <ArrowLeft size={16} />
            {t('listaPage.back')}
          </Link>
          <div className="flex items-center gap-2">
            {(['en', 'pt', 'ru'] as const).map((code) => (
              <button
                key={code}
                type="button"
                onClick={() => i18n.changeLanguage(code)}
                className={cn(
                  'rounded-full px-2.5 py-1 text-xs font-semibold transition-colors',
                  i18n.language.startsWith(code)
                    ? 'bg-primary text-primary-foreground'
                    : 'text-muted-foreground hover:text-foreground',
                )}
              >
                {code.toUpperCase()}
              </button>
            ))}
            <button
              type="button"
              onClick={toggleTheme}
              className="flex h-9 w-9 items-center justify-center rounded-full text-muted-foreground hover:bg-secondary/80 dark:hover:bg-white/[0.06]"
              aria-label="Toggle theme"
            >
              {theme === 'dark' ? <Sun size={16} /> : <Moon size={16} />}
            </button>
          </div>
        </div>
      </header>

      <main className="container py-10 md:py-14">
        <div className="mx-auto max-w-xl">
          <p className="eyebrow mb-3">{t('listaPage.eyebrow')}</p>
          <h1 className="mb-4 text-balance text-2xl font-semibold tracking-tight md:text-3xl">
            {t('listaPage.title')}
          </h1>
          <p className="mb-6 text-[0.9375rem] leading-[1.65] text-muted-foreground dark:text-neutral-400">
            {t('listaPage.subtitle')}
          </p>
          <p className="mb-8 text-sm text-foreground">
            <span className="font-semibold">{t('listaPage.nextLabel')}</span>
            <span className="text-muted-foreground"> — {dateShort}</span>
          </p>
          <ul className="mb-10 space-y-2.5 text-sm text-muted-foreground dark:text-neutral-400">
            {bullets.map((line) => (
              <li key={line} className="flex gap-2">
                <span className="text-emerald-600 dark:text-emerald-400" aria-hidden>
                  ·
                </span>
                <span>{line}</span>
              </li>
            ))}
          </ul>
          <div className="flex flex-col gap-3 sm:flex-row sm:flex-wrap">
            <a
              href={waLista}
              target="_blank"
              rel="noopener noreferrer"
              onClick={() => trackCta('cta_lista_whatsapp', { source: 'lista_page' })}
              className="inline-flex items-center justify-center gap-2 rounded-full bg-primary px-6 py-3 text-sm font-semibold text-primary-foreground transition-opacity hover:opacity-90"
            >
              {t('listaPage.ctaWa')}
              <ArrowUpRight size={16} aria-hidden />
            </a>
            <Link
              to="/sprint"
              onClick={() => trackCta('cta_lista_go_sprint', { source: 'lista_page', destination: 'sprint' })}
              className="inline-flex items-center justify-center gap-2 rounded-full border border-border px-6 py-3 text-sm font-semibold text-foreground transition-colors hover:bg-secondary/80 dark:hover:bg-white/[0.06]"
            >
              {t('listaPage.ctaSprint')}
              <ArrowUpRight size={16} className="opacity-80" aria-hidden />
            </Link>
          </div>
        </div>
      </main>
    </div>
  );
}
