import { ArrowUpRight } from 'lucide-react';
import { useTranslation } from 'react-i18next';
import { whatsappMessageHref } from '@/lib/whatsapp';
import { trackCta } from '@/lib/tracking';

const FOOTER_LINKS: { id: string; labelKey: string }[] = [
  { id: 'trabalhos', labelKey: 'nav.work' },
  { id: 'como', labelKey: 'nav.howWeWork' },
  { id: 'pacotes', labelKey: 'nav.pricing' },
  { id: 'sobre', labelKey: 'nav.about' },
  { id: 'depoimentos', labelKey: 'nav.testimonials' },
  { id: 'cta-final', labelKey: 'nav.contact' },
];

export default function Footer() {
  const { t } = useTranslation();
  const year = new Date().getFullYear();

  const go = (id: string) => {
    const el = document.getElementById(id);
    if (el) el.scrollIntoView({ behavior: 'smooth' });
  };

  const waLink = whatsappMessageHref(t('whatsapp.defaultLead'));
  const contactLinks = [
    { name: t('footer.contactWhatsapp'), href: waLink, external: true },
    { name: t('footer.contactEmail'), href: 'mailto:contato@maurosilvastudio.com.br', external: false },
  ];

  return (
    <footer id="contact" className="w-full bg-neutral-950 text-zinc-100" style={{ paddingBlock: 'var(--space-lg)' }}>
      <div className="container">
        <div className="mb-20 md:mb-28">
          <p className="eyebrow mb-6" style={{ color: '#888' }}>{t('footerCta.eyebrow')}</p>
          <h2 className="text-white font-bold mb-5 md:mb-6" style={{ fontSize: 'var(--text-section)', lineHeight: 'var(--leading-tight)' }}>
            {t('footerCta.title1')}<br />{t('footerCta.title2')}
          </h2>
          <p className="text-sm text-white/55 max-w-2xl leading-relaxed mb-8 md:mb-10">
            {t('footer.miniBio')}
          </p>
          <a href={waLink} target="_blank" rel="noopener noreferrer"
            onClick={() => trackCta('cta_footer_whatsapp', { source: 'footer' })}
            className="group inline-flex items-center gap-2 border border-white/10 text-white text-sm font-medium px-5 py-2.5 rounded-full hover:bg-white/5 transition-colors">
            <span>{t('footerCta.cta')}</span>
            <ArrowUpRight size={14} className="transition-transform group-hover:translate-x-0.5 group-hover:-translate-y-0.5" />
          </a>
        </div>

        <div className="flex flex-col md:flex-row md:justify-end gap-12 md:gap-40 mb-16">
          <nav className="flex flex-col gap-3" aria-label={t('footer.sectionNav')}>
            {FOOTER_LINKS.map(({ id, labelKey }) => (
              <button
                key={id}
                type="button"
                onClick={() => go(id)}
                className="text-left text-sm text-white/50 hover:text-white transition-colors"
              >
                {t(labelKey)}
              </button>
            ))}
          </nav>
          <div className="flex flex-col gap-3">
            {contactLinks.map((item) => (
              <a key={item.name} href={item.href} target={item.external ? '_blank' : undefined} rel={item.external ? 'noopener noreferrer' : undefined}
                onClick={() => trackCta('cta_footer_contact_link', { source: 'footer', channel: item.name })}
                className="group flex items-center gap-1 text-sm text-white/50 hover:text-white transition-colors">
                <span>{item.name}</span>
                <ArrowUpRight size={12} className="transition-transform group-hover:translate-x-0.5 group-hover:-translate-y-0.5" />
              </a>
            ))}
          </div>
        </div>

        <div className="pt-6 border-t border-white/[0.05]">
          <p className="text-xs text-[#8a8a8a]">{t('footer.copyright', { year })}</p>
        </div>
      </div>
    </footer>
  );
}
