export type FxSnapshot = {
  brlPerUsd: number;
  rubPerUsd: number;
  /** ISO date from API, or empty when using fallback only */
  date: string;
};

/** Taxas conservadoras se a API falhar (valores aproximados). */
export const FX_FALLBACK: FxSnapshot = {
  brlPerUsd: 4.88,
  rubPerUsd: 92,
  date: '',
};

const FRANKFURTER = 'https://api.frankfurter.app/latest?from=USD&to=BRL,RUB';
const ER_API = 'https://open.er-api.com/v6/latest/USD';

export async function fetchUsdToBrlRub(): Promise<FxSnapshot> {
  const tryFrankfurter = async (): Promise<FxSnapshot | null> => {
    const res = await fetch(FRANKFURTER);
    if (!res.ok) return null;
    const data = (await res.json()) as { date: string; rates: { BRL?: number; RUB?: number } };
    const brl = data.rates.BRL;
    const rub = data.rates.RUB;
    if (typeof brl !== 'number' || typeof rub !== 'number' || !Number.isFinite(brl) || !Number.isFinite(rub)) {
      return null;
    }
    return { brlPerUsd: brl, rubPerUsd: rub, date: data.date };
  };

  const tryErApi = async (): Promise<FxSnapshot | null> => {
    const res = await fetch(ER_API);
    if (!res.ok) return null;
    const data = (await res.json()) as {
      result?: string;
      time_last_update_utc?: string;
      rates?: { BRL?: number; RUB?: number };
    };
    if (data.result !== 'success') return null;
    const brl = data.rates?.BRL;
    const rub = data.rates?.RUB;
    if (typeof brl !== 'number' || typeof rub !== 'number' || !Number.isFinite(brl) || !Number.isFinite(rub)) {
      return null;
    }
    const date =
      data.time_last_update_utc != null
        ? new Date(data.time_last_update_utc).toISOString().slice(0, 10)
        : '';
    return { brlPerUsd: brl, rubPerUsd: rub, date };
  };

  const a = await tryFrankfurter();
  if (a) return a;
  const b = await tryErApi();
  if (b) return b;
  throw new Error('fx');
}
