import { Link } from 'react-router';
import { useTranslation } from 'react-i18next';
import { whatsappMessageHref } from '@/lib/whatsapp';
import { useExchangeRates } from '@/hooks/useExchangeRates';
import { currencyForLanguage, formatPriceForPlan } from '@/lib/formatLocalizedPrice';
import { trackCta } from '@/lib/tracking';

type Plan = {
  id: string;
  name: string;
  desc: string;
  priceNote: string;
  bullets: string[];
  cta: string;
  featured: boolean;
};

export default function Pricing() {
  const { t, i18n } = useTranslation();
  const plans = t('pricing.plans', { returnObjects: true }) as Plan[];
  const fx = useExchangeRates();
  const displayCurrency = currencyForLanguage(i18n.language);

  const waKeys: Record<string, string> = {
    sprint: 'whatsapp.pricingSprint',
    retainer: 'whatsapp.pricingRetainer',
    emergency: 'whatsapp.pricingEmergency',
  };

  const wa = (id: string) => whatsappMessageHref(t(waKeys[id] ?? 'whatsapp.defaultLead'));

  return (
    <section id="pacotes" className="layout-section w-full">
      <div className="container">
        <div className="measure-wide">
          <p className="eyebrow mb-4">{t('pricing.eyebrow')}</p>
          <h2
            className="text-foreground font-bold max-w-[22ch] mb-10 md:mb-12 text-balance"
            style={{ fontSize: 'var(--text-section)', lineHeight: 'var(--leading-tight)', letterSpacing: '-0.025em' }}
          >
            {t('pricing.title')}
          </h2>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-px rounded-2xl border border-border bg-border overflow-hidden items-stretch">
            {plans.map((plan) => (
              <div
                key={plan.id}
                className={`flex min-h-full flex-col p-7 md:p-8 transition-shadow duration-300 hover:shadow-lg ${
                  plan.featured
                    ? 'bg-foreground text-background shadow-xl'
                    : 'bg-background'
                }`}
              >
                <p className={`text-xs font-semibold uppercase tracking-[0.12em] mb-3 ${plan.featured ? 'text-background/70' : 'text-muted-foreground'}`}>
                  {plan.name}
                </p>
                <p className={`text-sm leading-[1.6] min-h-[3rem] mb-6 ${plan.featured ? 'text-background/85' : 'text-muted-foreground dark:text-neutral-400'}`}>{plan.desc}</p>
                <p className={`text-3xl md:text-4xl font-semibold tracking-tight mb-6 ${plan.featured ? 'text-background' : 'text-foreground'}`}>
                  {formatPriceForPlan(plan.id, displayCurrency, fx)}{' '}
                  <span className={`text-sm font-normal ${plan.featured ? 'text-background/60' : 'text-muted-foreground'}`}>{plan.priceNote}</span>
                </p>
                <ul className={`space-y-2.5 text-sm mb-8 flex-1 ${plan.featured ? 'text-background/90' : 'text-muted-foreground'}`}>
                  {plan.bullets.map((b, i) => (
                    <li
                      key={`${plan.id}-${i}`}
                      className={`flex gap-2 border-b border-dashed pb-2.5 last:border-0 last:pb-0 ${
                        plan.featured ? 'border-white/20' : 'border-border/60'
                      }`}
                    >
                      <span className={plan.featured ? 'text-emerald-400' : 'text-emerald-600 dark:text-emerald-400'} aria-hidden>
                        ✓
                      </span>
                      <span>{b}</span>
                    </li>
                  ))}
                </ul>
                {plan.id === 'sprint' ? (
                  <Link
                    to="/sprint"
                    onClick={() => trackCta('cta_pricing_plan', { source: 'pricing', plan: plan.id, destination: 'sprint' })}
                    className={`mt-auto inline-flex w-full items-center justify-center rounded-full py-3 text-sm font-semibold transition-opacity hover:opacity-90 ${
                      plan.featured
                        ? 'bg-background text-foreground'
                        : 'border border-border text-foreground hover:bg-secondary/80 dark:hover:bg-white/10'
                    }`}
                  >
                    {plan.cta}
                  </Link>
                ) : (
                  <a
                    href={wa(plan.id)}
                    target="_blank"
                    rel="noopener noreferrer"
                    onClick={() => trackCta('cta_pricing_plan', { source: 'pricing', plan: plan.id, destination: 'whatsapp' })}
                    className={`mt-auto inline-flex w-full items-center justify-center rounded-full py-3 text-sm font-semibold transition-opacity hover:opacity-90 ${
                      plan.featured
                        ? 'bg-background text-foreground'
                        : 'border border-border text-foreground hover:bg-secondary/80 dark:hover:bg-white/10'
                    }`}
                  >
                    {plan.cta}
                  </a>
                )}
              </div>
            ))}
          </div>
          <p className="mt-10 text-center text-sm text-muted-foreground dark:text-neutral-400 max-w-[36rem] mx-auto leading-[1.65]">{t('pricing.note')}</p>
        </div>
      </div>
    </section>
  );
}
