type TrackingPayload = Record<string, string | number | boolean | null | undefined>;

declare global {
  interface Window {
    dataLayer?: Array<Record<string, unknown>>;
    gtag?: (...args: unknown[]) => void;
  }
}

/**
 * Lightweight CTA tracker. Works with GTM/gtag if present, and keeps events available in dataLayer.
 */
export function trackCta(eventName: string, payload: TrackingPayload = {}) {
  if (typeof window === 'undefined') return;

  const eventPayload = { event: eventName, ...payload };

  window.dataLayer = window.dataLayer || [];
  window.dataLayer.push(eventPayload);

  if (typeof window.gtag === 'function') {
    window.gtag('event', eventName, payload);
  }
}
