export default function Services() {
  const ref = useRef<HTMLElement>(null);
  const [open, setOpen] = useState<number | null>(0);
  const { t, i18n } = useTranslation();
  const lang = i18n.language.split('-')[0];
  const full = data[lang] || data.en;
  const blocks = full.slice(1);

  useEffect(() => {
    const s = ref.current;
    if (!s) return;
    const left = s.querySelector('.como-left-anim');
    const ctx = gsap.context(() => {
      if (left) {
        gsap.fromTo(left.children, { opacity: 0, y: 20 }, {
          opacity: 1, y: 0, duration: 0.65, stagger: 0.08, ease: 'power3.out',
          scrollTrigger: { trigger: s, start: 'top 80%' },
        });
      }
    }, s);
    return () => ctx.revert();
  }, []);

  const serviceHref = (service: string, item: string) =>
    whatsappMessageHref(t('services.waInquiry', { service, item }));

  return (
    <section ref={ref} id="como" className="layout-section w-full">
      <div className="container grid grid-cols-1 gap-10 md:grid-cols-2 md:gap-12 lg:gap-16 items-start">
        <div className="como-left-anim">
          <p className="eyebrow mb-4 opacity-0">{t('services.eyebrow')}</p>
          <h2
            className="text-foreground font-bold text-balance max-w-[24ch] opacity-0"
            style={{
              fontSize: 'var(--text-section)',
              lineHeight: 'var(--leading-tight)',
              letterSpacing: '-0.025em',
            }}
          >
            {t('services.headingLead')}
            <span className="text-muted-foreground font-bold">{t('services.headingMuted')}</span>
          </h2>
          <p
            className="mt-6 max-w-[52ch] text-muted-foreground opacity-0 dark:text-neutral-400"
            style={{ fontSize: 'var(--text-body)', lineHeight: 'var(--leading-relaxed)', fontWeight: 500 }}
          >
            {t('services.intro')}
          </p>
        </div>
        <div className="min-w-0 w-full">
          {blocks.map((svc, i) => (
            <div key={svc.title} className="border-b border-border">
              <button
                type="button"
                onClick={() => setOpen(open === i ? null : i)}
                className="group flex w-full cursor-pointer items-center justify-between gap-4 py-[1.1rem] text-left"
              >
                <span className="font-semibold text-foreground" style={{ fontSize: 'var(--text-body)' }}>
                  {svc.title}
                </span>
                {open === i ? (
                  <ArrowUp size={20} className="shrink-0 text-muted-foreground" aria-hidden />
                ) : (
                  <ArrowDown size={20} className="shrink-0 text-muted-foreground transition-transform group-hover:translate-y-0.5" aria-hidden />
                )}
              </button>
              <div
                className="overflow-hidden transition-all duration-300 ease-out"
                style={{ maxHeight: open === i ? '900px' : '0', opacity: open === i ? 1 : 0 }}
              >
                <div className="space-y-1 pb-4">
                  {svc.items.map((item) => (
                    <a
                      key={item}
                      href={serviceHref(svc.title, item)}
                      target="_blank"
                      rel="noopener noreferrer"
                      className="group/item flex items-center justify-between py-2.5 text-sm text-muted-foreground transition-colors hover:text-foreground"
                    >
                      <span>{item}</span>
                      <span className="ml-3 shrink-0 text-xs opacity-0 transition-opacity group-hover/item:opacity-60">
                        {t('services.itemCta')}
                      </span>
                    </a>
                  ))}
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
}
