import { useEffect, useMemo, useState, type ChangeEvent } from 'react';
import { Link } from 'react-router';
import { useTranslation } from 'react-i18next';
import { format } from 'date-fns';
import { enUS, ptBR, ru } from 'date-fns/locale';
import { ArrowLeft, ArrowUpRight, Moon, Sun } from 'lucide-react';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { useTheme } from '@/hooks/useTheme';
import { suggestSprintWindow, type SprintTimeframe } from '@/lib/sprintWindow';
import { submitSprintInquiryEmail } from '@/lib/submitSprintEmail';
import { whatsappMessageHref } from '@/lib/whatsapp';
import { trackCta } from '@/lib/tracking';
import { cn } from '@/lib/utils';

type FormState = {
  name: string;
  email: string;
  company: string;
  role: string;
  timeframe: SprintTimeframe;
  notes: string;
};

const emptyForm: FormState = {
  name: '',
  email: '',
  company: '',
  role: '',
  timeframe: 'soon',
  notes: '',
};

function dateLocale(code: string) {
  if (code.startsWith('pt')) return ptBR;
  if (code.startsWith('ru')) return ru;
  return enUS;
}

export default function SprintInquiryPage() {
  const { t, i18n } = useTranslation();
  const { theme, toggleTheme } = useTheme();
  const [step, setStep] = useState<1 | 2 | 3>(1);
  const [form, setForm] = useState<FormState>(emptyForm);
  const [touched, setTouched] = useState(false);
  const [emailStatus, setEmailStatus] = useState<'idle' | 'loading' | 'error'>('idle');
  const [honeypot, setHoneypot] = useState('');

  const accessKey = import.meta.env.VITE_WEB3FORMS_ACCESS_KEY as string | undefined;

  const loc = dateLocale(i18n.language);

  useEffect(() => {
    const titles: Record<number, string> = {
      1: t('sprintPage.metaTitle'),
      2: t('sprintPage.metaTitle'),
      3: `${t('sprintPage.thankYouTitle')} · MAUROSILVASTUDIO`,
    };
    document.title = titles[step] ?? t('sprintPage.metaTitle');
    return () => {
      document.title = 'MAUROSILVASTUDIO · Studio de desenvolvimento para agências';
    };
  }, [t, step]);

  const windowDates = useMemo(
    () => suggestSprintWindow(form.timeframe),
    [form.timeframe],
  );

  const startStr = format(windowDates.start, 'PPP', { locale: loc });
  const endStr = format(windowDates.end, 'PPP', { locale: loc });

  const valid =
    form.name.trim().length > 0 &&
    form.email.trim().includes('@') &&
    form.company.trim().length > 0 &&
    !!form.timeframe;

  const timeframeLabel = t(`sprintPage.timeframe.${form.timeframe}`);

  const waAccept = whatsappMessageHref(
    t('sprintPage.waAccept', {
      name: form.name.trim(),
      email: form.email.trim(),
      company: form.company.trim(),
      role: form.role.trim() || '(none)',
      start: startStr,
      end: endStr,
      timeframe: timeframeLabel,
      notes: form.notes.trim() || '(none)',
    }),
  );

  const waTalk = whatsappMessageHref(
    t('sprintPage.waTalk', {
      name: form.name.trim(),
      email: form.email.trim(),
      company: form.company.trim(),
      start: startStr,
      end: endStr,
    }),
  );

  const REPLY_HOURS = 24;

  const sendSummaryEmail = async () => {
    if (honeypot.trim()) return;
    const key = accessKey?.trim();
    if (!key) return;
    setEmailStatus('loading');
    const { ok } = await submitSprintInquiryEmail({
      accessKey: key,
      name: form.name.trim(),
      email: form.email.trim(),
      company: form.company.trim(),
      role: form.role.trim(),
      timeframe: timeframeLabel,
      notes: form.notes.trim(),
      suggestedStart: startStr,
      suggestedEnd: endStr,
      locale: i18n.language,
      botcheck: honeypot,
    });
    setEmailStatus('idle');
    if (ok) setStep(3);
    else setEmailStatus('error');
  };

  const resetFlow = () => {
    setForm(emptyForm);
    setStep(1);
    setTouched(false);
    setEmailStatus('idle');
    setHoneypot('');
  };

  const goSummary = () => {
    setTouched(true);
    if (!valid) return;
    setStep(2);
  };

  const field = (key: keyof FormState) => (e: ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) =>
    setForm((f) => ({ ...f, [key]: e.target.value }));

  return (
    <div className="min-h-screen bg-white dark:bg-[#0A0A0A] text-foreground transition-colors duration-300">
      <header className="border-b border-border">
        <div className="container flex items-center justify-between h-14 md:h-16">
          <Link
            to="/"
            className="inline-flex items-center gap-2 text-sm text-muted-foreground hover:text-foreground transition-colors"
          >
            <ArrowLeft size={16} />
            {t('sprintPage.back')}
          </Link>
          <div className="flex items-center gap-2">
            {(['en', 'pt', 'ru'] as const).map((code) => (
              <button
                key={code}
                type="button"
                onClick={() => i18n.changeLanguage(code)}
                className={cn(
                  'text-xs font-semibold px-2.5 py-1 rounded-full transition-colors',
                  i18n.language === code
                    ? 'bg-foreground text-background'
                    : 'text-muted-foreground hover:text-foreground',
                )}
              >
                {code.toUpperCase()}
              </button>
            ))}
            <button
              type="button"
              onClick={toggleTheme}
              className="w-9 h-9 flex items-center justify-center rounded-full text-muted-foreground hover:bg-black/5 dark:hover:bg-white/5"
              aria-label="Toggle theme"
            >
              {theme === 'dark' ? <Sun size={16} /> : <Moon size={16} />}
            </button>
          </div>
        </div>
      </header>

      <main className="container py-10 md:py-14">
        <div className="mx-auto max-w-xl">
          <p className="eyebrow mb-3">
            {step === 1 ? t('sprintPage.eyebrowForm') : step === 2 ? t('sprintPage.eyebrowSummary') : t('sprintPage.eyebrowThanks')}
          </p>
          <h1 className="text-2xl md:text-3xl font-medium tracking-tight text-balance mb-4">
            {step === 3 ? t('sprintPage.thankYouTitle') : t('sprintPage.title')}
          </h1>
          {step !== 3 ? (
            <p className="text-muted-foreground dark:text-neutral-400 leading-[1.65] text-[0.9375rem] mb-6">{t('sprintPage.subtitle')}</p>
          ) : (
            <p className="text-muted-foreground dark:text-neutral-400 leading-[1.65] text-[0.9375rem] mb-8">
              {t('sprintPage.thankYouBody', { hours: REPLY_HOURS })}
            </p>
          )}

          {step === 3 ? (
            <div className="space-y-6">
              <a
                href={waTalk}
                target="_blank"
                rel="noopener noreferrer"
                onClick={() => trackCta('cta_sprint_thankyou_whatsapp', { source: 'sprint_page', step: 'thank_you' })}
                className="inline-flex w-full sm:w-auto items-center justify-center gap-2 border border-border text-foreground text-sm font-semibold px-6 py-3.5 rounded-full hover:bg-black/[0.03] dark:hover:bg-white/[0.06] transition-colors"
              >
                {t('sprintPage.thankYouWa')}
                <ArrowUpRight size={14} />
              </a>
              <div className="flex flex-col sm:flex-row gap-3 pt-2">
                <button
                  type="button"
                  onClick={resetFlow}
                  className="inline-flex flex-1 items-center justify-center gap-2 bg-foreground text-background text-sm font-semibold px-6 py-3.5 rounded-full hover:opacity-90 transition-opacity"
                >
                  {t('sprintPage.newRequest')}
                </button>
                <Link
                  to="/"
                  className="inline-flex flex-1 items-center justify-center gap-2 border border-border text-foreground text-sm font-semibold px-6 py-3.5 rounded-full hover:bg-black/[0.03] dark:hover:bg-white/[0.06] transition-colors text-center"
                >
                  {t('sprintPage.backHome')}
                </Link>
              </div>
            </div>
          ) : step === 1 ? (
            <form
              className="space-y-6"
              onSubmit={(e) => {
                e.preventDefault();
                goSummary();
              }}
            >
              <div className="space-y-2">
                <Label htmlFor="sp-name">{t('sprintPage.labels.name')}</Label>
                <Input id="sp-name" value={form.name} onChange={field('name')} autoComplete="name" required />
              </div>
              <div className="space-y-2">
                <Label htmlFor="sp-email">{t('sprintPage.labels.email')}</Label>
                <Input id="sp-email" type="email" value={form.email} onChange={field('email')} autoComplete="email" required />
              </div>
              <div className="space-y-2">
                <Label htmlFor="sp-company">{t('sprintPage.labels.company')}</Label>
                <Input id="sp-company" value={form.company} onChange={field('company')} autoComplete="organization" required />
              </div>
              <div className="space-y-2">
                <Label htmlFor="sp-role">{t('sprintPage.labels.role')}</Label>
                <Input id="sp-role" value={form.role} onChange={field('role')} placeholder={t('sprintPage.placeholders.role')} />
              </div>
              <div className="space-y-2">
                <Label htmlFor="sp-time">{t('sprintPage.labels.timeframe')}</Label>
                <select
                  id="sp-time"
                  value={form.timeframe}
                  onChange={(e) => setForm((f) => ({ ...f, timeframe: e.target.value as SprintTimeframe }))}
                  className={cn(
                    'flex h-10 w-full rounded-md border border-input px-3 py-2 text-sm shadow-xs outline-none',
                    'bg-white text-neutral-900',
                    'dark:bg-neutral-950 dark:text-neutral-100',
                    '[&>option]:bg-white [&>option]:text-neutral-900',
                    'dark:[&>option]:bg-neutral-950 dark:[&>option]:text-neutral-100',
                    'focus-visible:border-ring focus-visible:ring-ring/50 focus-visible:ring-[3px]',
                  )}
                >
                  <option value="asap">{t('sprintPage.timeframe.asap')}</option>
                  <option value="soon">{t('sprintPage.timeframe.soon')}</option>
                  <option value="flex">{t('sprintPage.timeframe.flex')}</option>
                </select>
              </div>
              <div className="space-y-2">
                <Label htmlFor="sp-notes">{t('sprintPage.labels.notes')}</Label>
                <Textarea
                  id="sp-notes"
                  value={form.notes}
                  onChange={field('notes')}
                  placeholder={t('sprintPage.placeholders.notes')}
                  rows={4}
                  className="min-h-[120px] resize-y"
                />
              </div>
              {touched && !valid ? <p className="text-sm text-destructive">{t('sprintPage.requiredHint')}</p> : null}
              <button
                type="submit"
                className="w-full inline-flex items-center justify-center gap-2 bg-foreground text-background text-sm font-semibold px-6 py-3.5 rounded-full hover:opacity-90 transition-opacity"
              >
                {t('sprintPage.continue')}
                <ArrowUpRight size={14} />
              </button>
            </form>
          ) : (
            <div className="space-y-8">
              <div className="rounded-2xl border border-border bg-secondary/30 dark:bg-white/[0.04] p-6 md:p-8">
                <p className="eyebrow mb-2">{t('sprintPage.summaryTitle')}</p>
                <p className="text-lg md:text-xl font-medium text-foreground mb-2">
                  {t('sprintPage.summaryRange', { start: startStr, end: endStr })}
                </p>
                <p className="text-sm text-muted-foreground dark:text-neutral-400 leading-[1.65]">{t('sprintPage.summaryNote')}</p>
              </div>

              <div>
                <p className="text-sm font-semibold text-foreground mb-3">{t('sprintPage.yourDetails')}</p>
                <ul className="text-sm text-muted-foreground dark:text-neutral-400 space-y-1.5 leading-relaxed">
                  <li>
                    <span className="text-foreground/80">{form.name}</span> · {form.email}
                  </li>
                  <li>{form.company}</li>
                  {form.role.trim() ? <li>{form.role}</li> : null}
                  <li>{timeframeLabel}</li>
                  {form.notes.trim() ? <li className="pt-2 whitespace-pre-wrap">{form.notes}</li> : null}
                </ul>
              </div>

              <button
                type="button"
                onClick={() => setStep(1)}
                className="text-sm font-medium text-muted-foreground hover:text-foreground underline underline-offset-4"
              >
                {t('sprintPage.edit')}
              </button>

              <div className="flex flex-col sm:flex-row gap-3 pt-2">
                <a
                  href={waAccept}
                  target="_blank"
                  rel="noopener noreferrer"
                  onClick={() => trackCta('cta_sprint_accept_whatsapp', { source: 'sprint_page', step: 'summary' })}
                  className="inline-flex flex-1 items-center justify-center gap-2 bg-foreground text-background text-sm font-semibold px-6 py-3.5 rounded-full hover:opacity-90 transition-opacity"
                >
                  {t('sprintPage.acceptProposal')}
                  <ArrowUpRight size={14} />
                </a>
                <a
                  href={waTalk}
                  target="_blank"
                  rel="noopener noreferrer"
                  onClick={() => trackCta('cta_sprint_talk_whatsapp', { source: 'sprint_page', step: 'summary' })}
                  className="inline-flex flex-1 items-center justify-center gap-2 border border-border text-foreground text-sm font-semibold px-6 py-3.5 rounded-full hover:bg-black/[0.03] dark:hover:bg-white/[0.06] transition-colors"
                >
                  {t('sprintPage.wantToTalk')}
                  <ArrowUpRight size={14} />
                </a>
              </div>

              <div className="relative border-t border-border pt-8">
                <p className="text-sm font-semibold text-foreground mb-4">{t('sprintPage.stepDivider')}</p>
                <div className="hidden" aria-hidden="true">
                  <input
                    id="sp-bot"
                    name="botcheck"
                    type="text"
                    tabIndex={-1}
                    autoComplete="off"
                    value={honeypot}
                    onChange={(e) => setHoneypot(e.target.value)}
                  />
                </div>
                {!accessKey?.trim() ? (
                  <p className="text-sm text-muted-foreground dark:text-neutral-400 leading-relaxed mb-4">{t('sprintPage.emailConfigHint')}</p>
                ) : null}
                <button
                  type="button"
                  onClick={sendSummaryEmail}
                  disabled={emailStatus === 'loading' || !accessKey?.trim() || !!honeypot.trim()}
                  className="w-full sm:w-auto inline-flex items-center justify-center gap-2 border border-border text-foreground text-sm font-semibold px-6 py-3.5 rounded-full hover:bg-black/[0.03] dark:hover:bg-white/[0.06] transition-colors disabled:opacity-50 disabled:pointer-events-none"
                >
                  {emailStatus === 'loading' ? t('sprintPage.sendingEmail') : t('sprintPage.sendEmailSummary')}
                  {emailStatus !== 'loading' ? <ArrowUpRight size={14} /> : null}
                </button>
                {emailStatus === 'error' ? <p className="text-sm text-destructive mt-3">{t('sprintPage.emailError')}</p> : null}
              </div>
            </div>
          )}
        </div>
      </main>
    </div>
  );
}
