import { useEffect, useRef, useState } from 'react';
import { Link, useLocation } from 'react-router';
import { ArrowUpRight, ChevronDown, Languages, Moon, Sun, Menu, X } from 'lucide-react';
import { useTranslation } from 'react-i18next';
import { useTheme } from '../hooks/useTheme';
import { whatsappMessageHref } from '@/lib/whatsapp';
import { trackCta } from '@/lib/tracking';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu';

interface NavbarProps {
  onNavigate: (target: string) => void;
}

const LANG_OPTIONS = [
  { code: 'en', label: 'English' },
  { code: 'pt', label: 'Português' },
  { code: 'ru', label: 'Русский' },
] as const;

export default function Navbar({ onNavigate }: NavbarProps) {
  const [hidden, setHidden] = useState(false);
  const [open, setOpen] = useState(false);
  const lastScrollY = useRef(0);
  const { pathname } = useLocation();
  const isHome = pathname === '/';
  const { t, i18n } = useTranslation();
  const { theme, toggleTheme } = useTheme();

  useEffect(() => {
    const handleScroll = () => {
      const y = window.scrollY;
      setHidden(y > 80 && y > lastScrollY.current);
      lastScrollY.current = y;
    };
    window.addEventListener('scroll', handleScroll, { passive: true });
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const handleNav = (id: string) => {
    onNavigate(id);
    setOpen(false);
  };
  const handleLang = (code: string) => {
    i18n.changeLanguage(code);
    setOpen(false);
  };

  const links = [
    { id: 'trabalhos', label: t('nav.work') },
    { id: 'sobre', label: t('nav.about') },
    { id: 'pacotes', label: t('nav.pricing') },
    { id: 'cta-final', label: t('nav.contact') },
  ];

  const waLink = whatsappMessageHref(t('whatsapp.defaultLead'));
  const langKey = (['en', 'pt', 'ru'] as const).find((c) => i18n.language.startsWith(c)) ?? 'en';
  const currentLangLabel = LANG_OPTIONS.find((l) => l.code === langKey)?.label ?? 'English';

  return (
    <>
      <nav
        className="fixed top-0 left-0 right-0 z-[100] border-b border-border bg-background/[0.85] backdrop-blur-[12px] transition-transform duration-300"
        style={{ transform: hidden && !open ? 'translateY(-100%)' : 'translateY(0)' }}
      >
        <div className="container flex min-h-0 items-center justify-between gap-4 py-[1.1rem]">
          {isHome ? (
            <button
              type="button"
              onClick={() => handleNav('hero')}
              className="text-[length:var(--text-sm)] font-bold uppercase tracking-[0.06em] text-foreground"
            >
              {t('nav.home')}
            </button>
          ) : (
            <Link to="/" className="text-[length:var(--text-sm)] font-bold uppercase tracking-[0.06em] text-foreground">
              {t('nav.home')}
            </Link>
          )}

          <div className="hidden items-center gap-8 md:flex">
            {links.map((l) =>
              isHome ? (
                <button
                  key={l.id}
                  type="button"
                  onClick={() => handleNav(l.id)}
                  className="split-hover text-sm font-medium text-muted-foreground transition-colors hover:text-foreground"
                >
                  <span data-text={l.label}>{l.label}</span>
                </button>
              ) : (
                <Link
                  key={l.id}
                  to={`/#${l.id}`}
                  className="split-hover text-sm font-medium text-muted-foreground transition-colors hover:text-foreground"
                >
                  <span data-text={l.label}>{l.label}</span>
                </Link>
              ),
            )}
          </div>

          <div className="flex items-center gap-2 md:gap-3">
            <DropdownMenu>
              <DropdownMenuTrigger
                type="button"
                className="hidden h-9 items-center gap-1.5 rounded-full border border-border px-2.5 text-xs font-semibold text-muted-foreground transition-colors hover:bg-secondary/80 dark:hover:bg-white/[0.06] md:inline-flex"
              >
                <Languages className="size-4 shrink-0 opacity-70" aria-hidden="true" />
                <span className="max-w-[5.5rem] truncate sm:max-w-none">{currentLangLabel}</span>
                <ChevronDown className="size-3.5 shrink-0 opacity-60" aria-hidden="true" />
              </DropdownMenuTrigger>
              <DropdownMenuContent align="end" className="z-[200] min-w-[10rem]">
                {LANG_OPTIONS.map(({ code, label }) => (
                  <DropdownMenuItem
                    key={code}
                    className="cursor-pointer"
                    onSelect={() => handleLang(code)}
                  >
                    <span className="flex-1">{label}</span>
                    {langKey === code ? (
                      <span className="text-xs text-muted-foreground" aria-hidden>
                        ✓
                      </span>
                    ) : null}
                  </DropdownMenuItem>
                ))}
              </DropdownMenuContent>
            </DropdownMenu>

            <button
              type="button"
              onClick={toggleTheme}
              className="flex h-9 w-9 items-center justify-center rounded-full border border-border text-muted-foreground transition-colors hover:bg-secondary/80 dark:hover:bg-white/[0.06]"
              aria-label="Toggle dark mode"
            >
              {theme === 'dark' ? <Sun size={16} /> : <Moon size={16} />}
            </button>

            <a
              href={waLink}
              target="_blank"
              rel="noopener noreferrer"
              onClick={() => trackCta('cta_nav_whatsapp', { source: 'navbar', viewport: 'desktop' })}
              className="hidden items-center gap-1.5 rounded-full bg-primary px-4 py-2 text-xs font-semibold text-primary-foreground transition-opacity hover:opacity-90 md:inline-flex"
            >
              <span>{t('nav.letsTalk')}</span>
              <ArrowUpRight size={12} aria-hidden="true" />
            </a>

            <button
              type="button"
              onClick={() => setOpen(!open)}
              className="flex h-9 w-9 items-center justify-center text-foreground md:hidden"
            >
              {open ? <X size={20} /> : <Menu size={20} />}
            </button>
          </div>
        </div>
      </nav>

      <div
        className="fixed inset-0 z-[99] transition-all duration-300 md:hidden"
        style={{ pointerEvents: open ? 'auto' : 'none', opacity: open ? 1 : 0 }}
      >
        <div className="absolute inset-0 bg-black/20 backdrop-blur-sm" onClick={() => setOpen(false)} />
        <div
          className="absolute right-0 top-0 flex h-full w-full max-w-sm flex-col justify-between bg-background p-8 pt-24 transition-transform duration-300"
          style={{ transform: open ? 'translateX(0)' : 'translateX(100%)' }}
        >
          <div className="flex flex-col gap-6">
            {links.map((l) =>
              isHome ? (
                <button
                  key={l.id}
                  type="button"
                  onClick={() => handleNav(l.id)}
                  className="text-left text-3xl font-medium text-foreground"
                >
                  {l.label}
                </button>
              ) : (
                <Link
                  key={l.id}
                  to={`/#${l.id}`}
                  onClick={() => setOpen(false)}
                  className="block text-left text-3xl font-medium text-foreground"
                >
                  {l.label}
                </Link>
              ),
            )}
            <a
              href={waLink}
              target="_blank"
              rel="noopener noreferrer"
              onClick={() => trackCta('cta_nav_whatsapp', { source: 'navbar', viewport: 'mobile' })}
              className="mt-4 inline-flex items-center gap-2 self-start rounded-full bg-primary px-5 py-3 text-sm font-semibold text-primary-foreground"
            >
              <span>{t('nav.letsTalk')}</span>
              <ArrowUpRight size={14} aria-hidden="true" />
            </a>
          </div>
          <div className="flex flex-col gap-5 border-t border-border pt-6">
            <button
              type="button"
              onClick={toggleTheme}
              className="flex items-center gap-3 text-sm text-muted-foreground"
            >
              {theme === 'dark' ? <Sun size={18} /> : <Moon size={18} />}
              <span>{theme === 'dark' ? 'Light' : 'Dark'}</span>
            </button>
            <div className="flex gap-2">
              {(['en', 'pt', 'ru'] as const).map((code) => (
                <button
                  key={code}
                  type="button"
                  onClick={() => handleLang(code)}
                  className={`rounded-full px-3 py-1.5 text-xs font-semibold transition-colors ${
                    i18n.language.startsWith(code)
                      ? 'bg-primary text-primary-foreground'
                      : 'bg-secondary text-muted-foreground'
                  }`}
                >
                  {code.toUpperCase()}
                </button>
              ))}
            </div>
          </div>
        </div>
      </div>
    </>
  );
}
