import { useTranslation } from 'react-i18next';

type Step = { title: string; desc: string };
type Guarantee = { title: string; desc: string };

export default function OperatingModel() {
  const { t } = useTranslation();
  const steps = t('operatingModel.steps', { returnObjects: true }) as Step[];
  const guarantees = t('operatingModel.guarantees', { returnObjects: true }) as Guarantee[];

  return (
    <section id="operacao" className="layout-section w-full">
      <div className="container">
        <div className="measure-wide">
          <p className="eyebrow mb-4">{t('operatingModel.eyebrow')}</p>
          <h2
            className="text-foreground font-bold max-w-[34ch] mb-10 md:mb-12 text-balance"
            style={{ fontSize: 'var(--text-section)', lineHeight: 'var(--leading-tight)', letterSpacing: '-0.02em' }}
          >
            {t('operatingModel.title')}
          </h2>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-4 md:gap-5 mb-8 md:mb-10">
            {steps.map((step, idx) => (
              <article key={step.title} className="rounded-2xl border border-border bg-card p-6 md:p-7">
                <p className="text-xs font-semibold uppercase tracking-[0.12em] text-muted-foreground mb-3">
                  {t('operatingModel.stepLabel')} {idx + 1}
                </p>
                <p className="text-sm font-semibold text-foreground mb-2 leading-snug">{step.title}</p>
                <p className="text-sm text-muted-foreground dark:text-neutral-400 leading-[1.65]">{step.desc}</p>
              </article>
            ))}
          </div>

          <div className="rounded-2xl border border-border bg-secondary/30 dark:bg-white/[0.04] p-6 md:p-8">
            <p className="text-sm font-semibold text-foreground mb-4">{t('operatingModel.guaranteeTitle')}</p>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-3 md:gap-4">
              {guarantees.map((item) => (
                <div key={item.title} className="rounded-xl border border-border/70 bg-background/70 px-4 py-3 dark:bg-transparent">
                  <p className="text-sm font-semibold text-foreground">{item.title}</p>
                  <p className="mt-1 text-xs leading-relaxed text-muted-foreground dark:text-neutral-400">{item.desc}</p>
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>
    </section>
  );
}
