import { useCallback, useEffect } from 'react';
import { useLocation } from 'react-router';
import { useLenis } from '../hooks/useLenis';
import Navbar from '../sections/Navbar';
import Hero from '../sections/Hero';
import SprintPromoStrip from '../sections/SprintPromoStrip';
import ClientLogos from '../sections/ClientLogos';
import Portfolio from '../sections/Portfolio';
import DesigningSuccess from '../sections/DesigningSuccess';
import Services from '../sections/Services';
import OperatingModel from '../sections/OperatingModel';
import OurStory from '../sections/OurStory';
import Testimonials from '../sections/Testimonials';
import Pricing from '../sections/Pricing';
import Faq from '../sections/Faq';
import Consulting from '../sections/Consulting';
import Footer from '../sections/Footer';
import { HOME_FIXED_HEADER_OFFSET_PX } from '@/lib/homeLayout';

export default function HomePage() {
  const lenisRef = useLenis();
  const { hash } = useLocation();

  useEffect(() => {
    const id = hash?.replace('#', '');
    if (!id) return;
    const run = () => {
      const el = document.getElementById(id);
      if (el && lenisRef.current) {
        lenisRef.current.scrollTo(el, { offset: -HOME_FIXED_HEADER_OFFSET_PX });
      } else {
        el?.scrollIntoView({ behavior: 'smooth' });
      }
    };
    const t = window.setTimeout(run, 80);
    return () => window.clearTimeout(t);
  }, [hash, lenisRef]);

  const handleNavigate = useCallback(
    (target: string) => {
      const element = document.getElementById(target);
      if (element && lenisRef.current) {
        lenisRef.current.scrollTo(element, { offset: -HOME_FIXED_HEADER_OFFSET_PX });
      }
    },
    [lenisRef],
  );

  return (
    <div className="min-h-screen bg-background transition-colors duration-300">
      <Navbar onNavigate={handleNavigate} />
      <main>
        <Hero />
        <SprintPromoStrip />
        <ClientLogos />
        <Portfolio />
        <DesigningSuccess />
        <Services />
        <OperatingModel />
        <OurStory />
        <Testimonials />
        <Pricing />
        <Faq />
        <Consulting />
      </main>
      <Footer />
    </div>
  );
}
