import { Link } from 'react-router';
import { ArrowUpRight } from 'lucide-react';
import { useTranslation } from 'react-i18next';
import { hasVaga, nextSprintDateDisplay } from '@/config/availability';
import { trackCta } from '@/lib/tracking';

/** Passive availability band + waitlist CTA so the row does not read as empty space. */
export default function SprintPromoStrip() {
  const { t } = useTranslation();
  const dateStr = nextSprintDateDisplay;

  return (
    <section
      aria-label={t('ctaStrip.a11yLabel')}
      className="w-full border-b border-border bg-background"
      style={{ paddingBlock: 'var(--space-md)' }}
    >
      <div className="container">
        <div className="flex flex-col gap-4 rounded-2xl border border-border/90 bg-muted/20 px-4 py-4 sm:px-6 sm:py-5 md:flex-row md:items-center md:justify-between md:gap-8 dark:border-neutral-800 dark:bg-neutral-950/60">
          <div className="min-w-0 space-y-2">
            <p className="text-[11px] font-medium uppercase tracking-[0.14em] text-foreground/70">
              {t('ctaStrip.eyebrow')}
            </p>
            <p className="text-sm font-semibold text-foreground">
              <span>{hasVaga ? t('sprintBar.slots') : t('sprintBar.slotsUnavailable')}</span>
              {hasVaga ? (
                <span className="font-normal text-foreground/70">
                  {' '}
                  · {t('sprintBar.detail', { date: dateStr })}
                </span>
              ) : null}
            </p>
            <p className="max-w-[52ch] text-xs leading-relaxed text-foreground/70">{t('ctaStrip.message')}</p>
          </div>
          <Link
            to="/lista"
            onClick={() => trackCta('cta_strip_waitlist', { source: 'sprint_strip', destination: 'lista' })}
            className="group inline-flex shrink-0 items-center justify-center gap-2 self-start rounded-full border border-border bg-background px-5 py-2.5 text-sm font-semibold text-foreground transition-colors hover:bg-foreground hover:text-background md:self-center dark:border-neutral-700 dark:hover:bg-foreground"
          >
            <span>{t('ctaStrip.cta')}</span>
            <ArrowUpRight
              size={14}
              className="transition-transform group-hover:translate-x-0.5 group-hover:-translate-y-0.5"
              aria-hidden
            />
          </Link>
        </div>
      </div>
    </section>
  );
}
