import { suggestSprintWindow } from '@/lib/sprintWindow';

/**
 * Data do próximo sprint exibida na faixa promocional; mesma lógica do formulário
 * /sprint (janela "asap"), portanto sempre no futuro em relação a `from`.
 */
export function nextPromoSprintStart(from: Date = new Date()): Date {
  return suggestSprintWindow('asap', from).start;
}
