import { useEffect, useRef } from 'react';
import { useTranslation } from 'react-i18next';
import gsap from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';

gsap.registerPlugin(ScrollTrigger);

export default function OurStory() {
  const ref = useRef<HTMLElement>(null);
  const { t } = useTranslation();

  useEffect(() => {
    const s = ref.current;
    if (!s) return;
    const ctx = gsap.context(() => {
      gsap.fromTo(s.children[0].children, { opacity: 0, y: 30 }, {
        opacity: 1, y: 0, duration: 0.8, stagger: 0.1, ease: 'power3.out',
        scrollTrigger: { trigger: s, start: 'top 80%' },
      });
    }, s);
    return () => ctx.revert();
  }, []);

  return (
    <section ref={ref} id="sobre" className="layout-section w-full">
      <div className="container grid grid-cols-1 md:grid-cols-[10rem_1fr] gap-8 md:gap-12 lg:gap-16 items-start">
        <p className="eyebrow opacity-0 md:pt-1">{t('ourStory.eyebrow')}</p>
        <p
          className="measure-prose opacity-0 text-balance text-black dark:text-white"
          style={{ fontSize: 'var(--text-section)', lineHeight: 'var(--leading-normal)', fontWeight: 400 }}
        >
          <span>{t('ourStory.textStart')}</span>
          <span className="text-[#737373] dark:text-neutral-500">{t('ourStory.textEnd')}</span>
        </p>
      </div>
    </section>
  );
}
