import { useEffect, useState } from 'react';
import { FX_FALLBACK, fetchUsdToBrlRub, type FxSnapshot } from '@/lib/exchangeRates';

const CACHE_KEY = 'mss-fx-usd-brl-rub-v1';
const CACHE_MS = 45 * 60 * 1000;
const REFRESH_MS = 60 * 60 * 1000;
const ENABLE_LIVE_FX = (import.meta.env.VITE_ENABLE_LIVE_FX as string | undefined) === 'true';

function readCache(): FxSnapshot | null {
  try {
    const raw = sessionStorage.getItem(CACHE_KEY);
    if (!raw) return null;
    const { t, ...fx } = JSON.parse(raw) as { t: number } & FxSnapshot;
    if (Date.now() - t > CACHE_MS) return null;
    if (typeof fx.brlPerUsd !== 'number' || typeof fx.rubPerUsd !== 'number') return null;
    return fx;
  } catch {
    return null;
  }
}

function writeCache(fx: FxSnapshot) {
  try {
    sessionStorage.setItem(CACHE_KEY, JSON.stringify({ ...fx, t: Date.now() }));
  } catch {
    /* ignore */
  }
}

/**
 * Taxas USD → BRL/RUB (Frankfurter / ECB), com cache em sessionStorage e re-fetch periódico.
 */
export function useExchangeRates(): FxSnapshot {
  const [fx, setFx] = useState<FxSnapshot>(() => readCache() ?? FX_FALLBACK);

  useEffect(() => {
    if (!ENABLE_LIVE_FX) {
      return;
    }

    let cancelled = false;

    const apply = (next: FxSnapshot) => {
      if (cancelled) return;
      writeCache(next);
      setFx(next);
    };

    const load = async () => {
      const cached = readCache();
      if (cached) apply(cached);
      try {
        const fresh = await fetchUsdToBrlRub();
        apply(fresh);
      } catch {
        if (!cached) apply(FX_FALLBACK);
      }
    };

    void load();
    const id = window.setInterval(() => void load(), REFRESH_MS);
    const onFocus = () => void load();
    window.addEventListener('focus', onFocus);
    return () => {
      cancelled = true;
      window.clearInterval(id);
      window.removeEventListener('focus', onFocus);
    };
  }, []);

  return fx;
}
