import { format } from 'date-fns';
import { nextPromoSprintStart } from '@/lib/nextPromoSprintStart';

const parseBool = (value: string | undefined, fallback: boolean): boolean => {
  if (!value) return fallback;
  return ['1', 'true', 'yes', 'on'].includes(value.toLowerCase());
};

/**
 * Public availability config so commercial toggles are not hardcoded in UI components.
 * Optional env vars:
 * - VITE_HAS_VAGA=true|false
 * - VITE_NEXT_SPRINT_DATE=dd/MM
 */
export const hasVaga = parseBool(import.meta.env.VITE_HAS_VAGA as string | undefined, true);

export const nextSprintDateDisplay =
  (import.meta.env.VITE_NEXT_SPRINT_DATE as string | undefined)?.trim() ||
  format(nextPromoSprintStart(), 'dd/MM');
