const localeKey = (code: string): 'en' | 'pt' | 'ru' => {
  if (code.startsWith('pt')) return 'pt';
  if (code.startsWith('ru')) return 'ru';
  return 'en';
};

export function getCaseContent(slug: string, language: string): CaseStudyContent | null {
  const row = CASE_INTERNOS.find((c) => c.slug === slug);
  if (!row) return null;
  return row[localeKey(language)];
}

export function getCaseRecord(slug: string): CaseStudyRecord | null {
  return CASE_INTERNOS.find((c) => c.slug === slug) ?? null;
}

export function listCaseSlugs(): string[] {
  return CASE_INTERNOS.map((c) => c.slug);
}

/** Plain text blob for reading-time estimate */
export function casePlainText(c: CaseStudyContent): string {
  return [
    c.title,
    c.dek,
    c.execSummary,
    c.context,
    c.challenge,
    c.solution,
    c.approach.join(' '),
    (c.outcomes ?? []).join(' '),
  ].join(' ');
}

export function estimateReadingMinutes(c: CaseStudyContent): number {
  const words = casePlainText(c).split(/\s+/).filter(Boolean).length;
  return Math.max(1, Math.round(words / 200));
}
