import { addDays, nextMonday } from 'date-fns';

export type SprintTimeframe = 'asap' | 'soon' | 'flex';

/** Indicative 2-week sprint window: next Monday after a buffer, 14 calendar days. */
export function suggestSprintWindow(timeframe: SprintTimeframe, from: Date = new Date()): { start: Date; end: Date } {
  const bufferDays = timeframe === 'asap' ? 7 : timeframe === 'soon' ? 14 : 28;
  const afterBuffer = addDays(from, bufferDays);
  const start = nextMonday(afterBuffer);
  const end = addDays(start, 13);
  return { start, end };
}
