import { PRICING_USD, type PricingPlanId } from '@/lib/pricingUsd';
import type { FxSnapshot } from '@/lib/exchangeRates';

export type DisplayCurrency = 'USD' | 'BRL' | 'RUB';

export function currencyForLanguage(lng: string): DisplayCurrency {
  if (lng.startsWith('pt')) return 'BRL';
  if (lng.startsWith('ru')) return 'RUB';
  return 'USD';
}

export function formatPriceForPlan(planId: string, currency: DisplayCurrency, fx: FxSnapshot): string {
  const usd = PRICING_USD[planId as PricingPlanId];
  if (usd == null) return '';

  if (currency === 'USD') {
    return new Intl.NumberFormat('en-US', {
      style: 'currency',
      currency: 'USD',
      maximumFractionDigits: 0,
    }).format(usd);
  }

  if (currency === 'BRL') {
    const v = usd * fx.brlPerUsd;
    return new Intl.NumberFormat('pt-BR', {
      style: 'currency',
      currency: 'BRL',
      maximumFractionDigits: 0,
    }).format(v);
  }

  const v = usd * fx.rubPerUsd;
  return new Intl.NumberFormat('ru-RU', {
    style: 'currency',
    currency: 'RUB',
    maximumFractionDigits: 0,
  }).format(v);
}
