import { useEffect } from 'react';
import { Link } from 'react-router';
import { useTranslation } from 'react-i18next';
import { ArrowUpRight } from 'lucide-react';
import { CaseInternoHeader } from '@/components/CaseInternoHeader';
import { CASE_INTERNOS, getCaseContent } from '@/data/casesInterno';

export default function CaseInternoIndexPage() {
  const { t, i18n } = useTranslation();

  useEffect(() => {
    document.title = t('caseInternoPage.metaIndexTitle');
    return () => {
      document.title = 'MAUROSILVASTUDIO · Studio de desenvolvimento para agências';
    };
  }, [t]);

  return (
    <div className="min-h-screen bg-background text-foreground transition-colors duration-300">
      <CaseInternoHeader backTo="/" backLabel={t('caseInternoPage.back')} />

      <main className="container py-10 md:py-14">
        <p className="eyebrow mb-3">{t('caseInternoPage.indexEyebrow')}</p>
        <h1 className="mb-4 max-w-3xl text-balance text-2xl font-semibold tracking-tight md:text-3xl">
          {t('caseInternoPage.indexTitle')}
        </h1>
        <p className="mb-12 max-w-2xl text-sm leading-relaxed text-muted-foreground md:text-base">
          {t('caseInternoPage.indexSubtitle')}
        </p>

        {CASE_INTERNOS.length === 0 ? (
          <p className="text-sm text-muted-foreground">{t('caseInternoPage.indexEmpty')}</p>
        ) : (
          <ul className="grid gap-6 md:grid-cols-2 lg:grid-cols-3">
            {CASE_INTERNOS.map((row) => {
              const c = getCaseContent(row.slug, i18n.language);
              if (!c) return null;
              return (
                <li key={row.slug}>
                  <Link
                    to={`/caseinterno/${row.slug}`}
                    className="group flex h-full flex-col rounded-2xl border border-border bg-card p-6 transition-colors hover:border-foreground/15 hover:bg-secondary/30 dark:hover:bg-white/[0.03]"
                  >
                    <p className="text-xs font-semibold uppercase tracking-[0.12em] text-muted-foreground">{c.category}</p>
                    <h2 className="mt-2 text-lg font-semibold text-foreground group-hover:underline-offset-4">{c.title}</h2>
                    <p className="mt-2 flex-1 text-sm leading-relaxed text-muted-foreground">{c.dek}</p>
                    <span className="mt-4 inline-flex items-center gap-1.5 text-sm font-medium text-foreground">
                      {t('caseInternoPage.viewCase')}
                      <ArrowUpRight size={14} className="transition-transform group-hover:translate-x-0.5 group-hover:-translate-y-0.5" />
                    </span>
                  </Link>
                </li>
              );
            })}
          </ul>
        )}
      </main>
    </div>
  );
}
