const WEB3FORMS_URL = 'https://api.web3forms.com/submit';

export type SprintEmailPayload = {
  accessKey: string;
  name: string;
  email: string;
  company: string;
  role: string;
  timeframe: string;
  notes: string;
  suggestedStart: string;
  suggestedEnd: string;
  locale: string;
  /** Honeypot: must stay empty */
  botcheck: string;
};

export async function submitSprintInquiryEmail(p: SprintEmailPayload): Promise<{ ok: boolean }> {
  if (!p.accessKey.trim()) return { ok: false };

  const message = [
    'Sprint availability form',
    '',
    `Name: ${p.name}`,
    `Email: ${p.email}`,
    `Company: ${p.company}`,
    `Role: ${p.role || '(none)'}`,
    `Timeframe: ${p.timeframe}`,
    `Locale: ${p.locale}`,
    '',
    'Suggested 2-week window:',
    `  Start: ${p.suggestedStart}`,
    `  End: ${p.suggestedEnd}`,
    '',
    'Notes:',
    p.notes.trim() || '(none)',
    '',
    'Target inbox: contato@maurosilvastudio.com.br (set in Web3Forms dashboard for this access key).',
  ].join('\n');

  const res = await fetch(WEB3FORMS_URL, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
    body: JSON.stringify({
      access_key: p.accessKey,
      subject: `[Sprint] ${p.company} | ${p.name}`,
      name: p.name,
      email: p.email,
      replyto: p.email,
      message,
      botcheck: p.botcheck,
    }),
  });

  let data: { success?: boolean } = {};
  try {
    data = (await res.json()) as { success?: boolean };
  } catch {
    return { ok: false };
  }

  return { ok: res.ok && data.success === true };
}
