import { useEffect, useRef } from 'react';
import { Link } from 'react-router';
import { ArrowUpRight } from 'lucide-react';
import { useTranslation } from 'react-i18next';
import gsap from 'gsap';
import { hasVaga, nextSprintDateDisplay } from '@/config/availability';
import { trackCta } from '@/lib/tracking';

export default function Hero() {
  const el = useRef<HTMLElement>(null);
  const { t } = useTranslation();

  useEffect(() => {
    const s = el.current;
    if (!s) return;
    const tl = gsap.timeline({ defaults: { ease: 'power3.out' } });
    const eyebrow = s.querySelector('.hero-eyebrow');
    const wordStart = eyebrow ? 0.35 : 0.2;
    if (eyebrow) tl.fromTo(eyebrow, { opacity: 0, y: 16 }, { opacity: 1, y: 0, duration: 0.6 }, 0.2);
    const titleBlock = s.querySelector('.hero-title-block');
    if (titleBlock) {
      tl.fromTo(titleBlock, { opacity: 0, y: 24 }, { opacity: 1, y: 0, duration: 0.75 }, wordStart);
    }
    const pillars = s.querySelectorAll('.hero-pillar');
    if (pillars.length) {
      tl.fromTo(pillars, { opacity: 0, y: 20 }, { opacity: 1, y: 0, duration: 0.55, stagger: 0.1 }, wordStart + 0.45);
    }
    const ctaEls = s.querySelectorAll('.hero-cta, .hero-secondary-text');
    if (ctaEls.length) {
      tl.fromTo(ctaEls, { opacity: 0, y: 12 }, { opacity: 1, y: 0, duration: 0.5, stagger: 0.08 }, wordStart + 0.85);
    }
    return () => {
      tl.kill();
    };
  }, [t, hasVaga]);

  return (
    <section
      ref={el}
      id="hero"
      className="w-full min-h-[80dvh] flex flex-col justify-center border-b border-border"
      style={{
        paddingBottom: 'var(--space-lg)',
        paddingTop: 'max(5rem, env(safe-area-inset-top, 0px))',
      }}
    >
      <div className="container w-full">
        <div className="max-w-4xl">
          {t('hero.eyebrow') ? (
            <p className="hero-eyebrow eyebrow mb-5 md:mb-6 opacity-0">{t('hero.eyebrow')}</p>
          ) : null}
          <h1
            className="hero-title-block mb-8 md:mb-10 text-balance text-pretty opacity-0"
            style={{
              fontSize: 'var(--text-hero)',
              lineHeight: 'var(--leading-tight)',
              fontWeight: 500,
              letterSpacing: '-0.02em',
            }}
          >
            <span className="text-foreground">{t('hero.titleStart')}</span>
            <span className="text-muted-foreground"> {t('hero.titleEnd')}</span>
          </h1>

          <div className="mb-10 md:mb-12 grid grid-cols-1 gap-0 border-t border-border md:grid-cols-2 md:[grid-template-columns:minmax(0,1fr)_minmax(0,1fr)]">
            <div className="hero-pillar opacity-0 min-w-0 w-full border-b border-border py-6 md:border-b-0 md:border-r md:border-border md:px-8 lg:px-10 md:py-8">
              <p className="hero-card-label eyebrow mb-2 tracking-[0.1em]">{t('hero.resultadosTitle')}</p>
              <p
                className="text-foreground font-semibold mb-2 w-full max-w-none text-balance"
                style={{ fontSize: 'var(--text-body)', lineHeight: 'var(--leading-normal)' }}
              >
                {t('hero.resultadosCardTitle')}
              </p>
              <p
                className="text-muted-foreground w-full max-w-none dark:text-neutral-400"
                style={{
                  fontSize: 'var(--text-sm)',
                  lineHeight: 'var(--leading-relaxed)',
                  fontWeight: 400,
                }}
              >
                {t('hero.resultadosBody')}
              </p>
            </div>
            <div className="hero-pillar opacity-0 min-w-0 w-full py-6 md:px-8 lg:px-10 md:py-8">
              <p className="hero-card-label eyebrow mb-2 tracking-[0.1em]">{t('hero.porqueTitle')}</p>
              <p
                className="text-foreground font-semibold mb-2 w-full max-w-none text-balance"
                style={{
                  fontSize: 'var(--text-body)',
                  lineHeight: 'var(--leading-normal)',
                }}
              >
                {t('hero.porqueQuestion')}
              </p>
              <p
                className="text-muted-foreground w-full max-w-none dark:text-neutral-400"
                style={{
                  fontSize: 'var(--text-sm)',
                  lineHeight: 'var(--leading-relaxed)',
                  fontWeight: 400,
                }}
              >
                {t('hero.porqueAnswer')}
              </p>
            </div>
          </div>

          <div className="hero-ctas flex flex-col sm:flex-row sm:flex-wrap items-stretch sm:items-center gap-3 sm:gap-x-6 sm:gap-y-2">
            {hasVaga ? (
              <>
                <Link
                  to="/sprint"
                  onClick={() => trackCta('cta_hero_start_sprint', { source: 'hero', destination: 'sprint' })}
                  className="hero-cta group inline-flex items-center justify-center gap-2 bg-foreground text-background text-sm font-semibold px-7 py-3.5 rounded-full hover:opacity-[0.88] transition-[opacity,transform] duration-300 opacity-0 active:scale-[0.98]"
                >
                  <span>{t('hero.ctaStartSprint')}</span>
                  <ArrowUpRight size={14} className="transition-transform group-hover:translate-x-0.5 group-hover:-translate-y-0.5" />
                </Link>
                <Link
                  to="/lista"
                  onClick={() => trackCta('cta_hero_waitlist', { source: 'hero', destination: 'lista' })}
                  className="hero-secondary-text text-sm text-muted-foreground underline-offset-4 decoration-muted-foreground/50 hover:text-foreground hover:decoration-foreground/40 opacity-0 sm:self-center"
                >
                  {t('hero.ctaListaInline')}
                </Link>
              </>
            ) : (
              <>
                <Link
                  to="/lista"
                  onClick={() => trackCta('cta_hero_waitlist', { source: 'hero', destination: 'lista' })}
                  className="hero-cta group inline-flex items-center justify-center gap-2 bg-foreground text-background text-sm font-semibold px-7 py-3.5 rounded-full hover:opacity-[0.88] transition-[opacity,transform] duration-300 opacity-0 active:scale-[0.98]"
                >
                  <span>{t('hero.ctaLista')}</span>
                  <ArrowUpRight size={14} className="transition-transform group-hover:translate-x-0.5 group-hover:-translate-y-0.5" />
                </Link>
                <p className="hero-secondary-text text-sm text-muted-foreground dark:text-neutral-400 opacity-0 sm:self-center">
                  {t('hero.nextSprintContext', { date: nextSprintDateDisplay })}
                </p>
              </>
            )}
          </div>
        </div>
      </div>
    </section>
  );
}
