import { Link } from 'react-router';
import { useTranslation } from 'react-i18next';
import { ArrowLeft, Moon, Sun } from 'lucide-react';
import { useTheme } from '@/hooks/useTheme';
import { cn } from '@/lib/utils';

type Props = {
  backTo: string;
  backLabel: string;
};

export function CaseInternoHeader({ backTo, backLabel }: Props) {
  const { i18n } = useTranslation();
  const { theme, toggleTheme } = useTheme();

  return (
    <header className="border-b border-border">
      <div className="container flex h-14 items-center justify-between md:h-16">
        <Link
          to={backTo}
          className="inline-flex items-center gap-2 text-sm text-muted-foreground transition-colors hover:text-foreground"
        >
          <ArrowLeft size={16} />
          {backLabel}
        </Link>
        <div className="flex items-center gap-2">
          {(['en', 'pt', 'ru'] as const).map((code) => (
            <button
              key={code}
              type="button"
              onClick={() => i18n.changeLanguage(code)}
              className={cn(
                'rounded-full px-2.5 py-1 text-xs font-semibold transition-colors',
                i18n.language.startsWith(code)
                  ? 'bg-primary text-primary-foreground'
                  : 'text-muted-foreground hover:text-foreground',
              )}
            >
              {code.toUpperCase()}
            </button>
          ))}
          <button
            type="button"
            onClick={toggleTheme}
            className="flex h-9 w-9 items-center justify-center rounded-full text-muted-foreground hover:bg-secondary/80 dark:hover:bg-white/[0.06]"
            aria-label="Toggle theme"
          >
            {theme === 'dark' ? <Sun size={16} /> : <Moon size={16} />}
          </button>
        </div>
      </div>
    </header>
  );
}
