import { useEffect, useMemo, useRef, useState, type ReactNode } from 'react';
import { Link } from 'react-router';
import { ArrowUpRight } from 'lucide-react';
import { useTranslation } from 'react-i18next';
import gsap from 'gsap';
import { cn } from '@/lib/utils';

/** Order matches `portfolio.projects[].assetIndex`. */
const images = [
  '/images/portfolio-plugin.jpg',
  '/images/portfolio-infographic.jpg',
  '/images/portfolio-mobile.jpg',
  '/images/portfolio-featured.jpg',
  '/images/portfolio-branding.jpg',
  '/images/portfolio-plugin.jpg',
];

type PortfolioProject = {
  assetIndex?: number;
  caseSlug?: string;
  category: string;
  title: string;
  caption?: string;
};

function ProjectCard({
  project: p,
  layout,
  children,
}: {
  project: PortfolioProject;
  layout: 'featured' | 'grid';
  children: ReactNode;
}) {
  const cls = cn(
    'port-item group block text-left opacity-0',
    layout === 'featured' ? 'mb-8 cursor-pointer' : 'cursor-pointer',
  );
  if (p.caseSlug) {
    return (
      <Link to={`/caseinterno/${p.caseSlug}`} className={cls}>
        {children}
      </Link>
    );
  }
  return <div className={cls}>{children}</div>;
}

function imageFor(p: PortfolioProject) {
  const idx = typeof p.assetIndex === 'number' ? p.assetIndex : 0;
  const i = Math.max(0, Math.min(idx, images.length - 1));
  return images[i] ?? images[0];
}

export default function Portfolio() {
  const ref = useRef<HTMLElement>(null);
  const { t, i18n } = useTranslation();
  const [activeFilter, setActiveFilter] = useState<'all' | string>('all');

  const projects = useMemo(
    () => t('portfolio.projects', { returnObjects: true }) as PortfolioProject[],
    [t, i18n.language],
  );

  const categories = useMemo(() => {
    const seen = new Set<string>();
    const order: string[] = [];
    for (const p of projects) {
      if (!seen.has(p.category)) {
        seen.add(p.category);
        order.push(p.category);
      }
    }
    return order;
  }, [projects]);

  const filtered = useMemo(() => {
    if (activeFilter === 'all') return projects;
    return projects.filter((p) => p.category === activeFilter);
  }, [projects, activeFilter]);

  const featured = filtered[0];
  const grid = filtered.slice(1);

  const filterSig = filtered.map((p) => `${p.assetIndex ?? 0}-${p.title}`).join(',');

  useEffect(() => {
    setActiveFilter('all');
  }, [i18n.language]);

  useEffect(() => {
    const s = ref.current;
    if (!s) return;
    const items = s.querySelectorAll('.port-item');
    if (!items.length) return;
    const ctx = gsap.context(() => {
      gsap.fromTo(
        items,
        { opacity: 0, y: 28 },
        { opacity: 1, y: 0, duration: 0.55, stagger: 0.07, ease: 'power3.out' },
      );
    }, s);
    return () => ctx.revert();
  }, [filterSig]);

  const pillClass = (on: boolean) =>
    cn(
      'shrink-0 rounded-full border px-3.5 py-1.5 text-xs font-semibold tracking-wide transition-colors',
      on
        ? 'border-foreground bg-foreground text-background'
        : 'border-border bg-transparent text-muted-foreground hover:border-foreground/20 hover:text-foreground',
    );

  return (
    <section ref={ref} id="trabalhos" className="layout-section w-full">
      <div className="container">
        <p className="eyebrow mb-4 md:mb-5">{t('nav.work')}</p>

        <div
          className="-mx-4 mb-8 flex gap-2 overflow-x-auto px-4 pb-1 md:mx-0 md:flex-wrap md:px-0 md:pb-0"
          role="tablist"
          aria-label={t('portfolio.filterLabel')}
        >
          <button
            type="button"
            role="tab"
            aria-selected={activeFilter === 'all'}
            onClick={() => setActiveFilter('all')}
            className={pillClass(activeFilter === 'all')}
          >
            {t('portfolio.filterAll')}
          </button>
          {categories.map((cat) => (
            <button
              key={cat}
              type="button"
              role="tab"
              aria-selected={activeFilter === cat}
              onClick={() => setActiveFilter(cat)}
              className={pillClass(activeFilter === cat)}
            >
              {cat}
            </button>
          ))}
        </div>

        {!featured ? (
          <p className="text-sm text-muted-foreground">{t('portfolio.filterEmpty')}</p>
        ) : (
          <>
            <ProjectCard project={featured} layout="featured">
              <div
                className="relative w-full overflow-hidden rounded-2xl bg-[#F5F5F5] dark:bg-[#141414]"
                style={{ aspectRatio: '16/9' }}
              >
                <img
                  src={imageFor(featured)}
                  alt={`${featured.category}: ${featured.title}`}
                  className="h-full w-full object-cover transition-transform duration-500 group-hover:scale-[1.02]"
                />
                <div className="absolute bottom-6 left-6">
                  <ArrowUpRight
                    size={22}
                    className="text-black transition-transform group-hover:translate-x-1 group-hover:-translate-y-1 dark:text-white"
                  />
                </div>
              </div>
              <div className="mt-5">
                <p className="text-xs font-medium uppercase tracking-[0.12em] text-muted-foreground dark:text-neutral-500">
                  {featured.category}
                </p>
                <p className="mt-1.5 text-sm font-medium text-black dark:text-white">{featured.title}</p>
                {featured.caption ? (
                  <p className="mt-2 max-w-[min(100%,56ch)] text-xs leading-[1.65] text-muted-foreground dark:text-neutral-500">
                    {featured.caption}
                  </p>
                ) : null}
              </div>
            </ProjectCard>

            {grid.length > 0 ? (
              <div className="grid grid-cols-1 gap-6 md:grid-cols-2">
                {grid.map((p) => (
                  <ProjectCard key={`${p.category}-${p.title}`} project={p} layout="grid">
                    <div
                      className="relative w-full overflow-hidden rounded-2xl bg-[#F5F5F5] dark:bg-[#141414]"
                      style={{ aspectRatio: '4/3' }}
                    >
                      <img
                        src={imageFor(p)}
                        alt={`${p.category}: ${p.title}`}
                        className="h-full w-full object-cover transition-transform duration-500 group-hover:scale-[1.02]"
                      />
                      <div className="absolute bottom-6 left-6">
                        <ArrowUpRight
                          size={22}
                          className="text-black transition-transform group-hover:translate-x-1 group-hover:-translate-y-1 dark:text-white"
                        />
                      </div>
                    </div>
                    <div className="mt-5">
                      <p className="text-xs font-medium uppercase tracking-[0.12em] text-muted-foreground dark:text-neutral-500">
                        {p.category}
                      </p>
                      <p className="mt-1.5 text-sm font-medium text-black dark:text-white">{p.title}</p>
                      {p.caption ? (
                        <p className="mt-2 max-w-[min(100%,48ch)] text-xs leading-[1.65] text-muted-foreground dark:text-neutral-500">
                          {p.caption}
                        </p>
                      ) : null}
                    </div>
                  </ProjectCard>
                ))}
              </div>
            ) : null}
          </>
        )}
      </div>
    </section>
  );
}
