import { useState } from 'react';
import { Plus } from 'lucide-react';
import { useTranslation } from 'react-i18next';

type FaqItem = { q: string; a: string };

export default function Faq() {
  const { t } = useTranslation();
  const items = t('faq.items', { returnObjects: true }) as FaqItem[];
  const [open, setOpen] = useState<number | null>(null);

  return (
    <section id="faq" className="layout-section w-full">
      <div className="container grid grid-cols-1 gap-10 md:grid-cols-2 md:gap-12 lg:gap-16 items-start">
        <div>
          <p className="eyebrow mb-4">{t('faq.eyebrow')}</p>
          <h2
            className="text-foreground font-bold text-balance max-w-[36rem]"
            style={{ fontSize: 'var(--text-section)', lineHeight: 'var(--leading-tight)', letterSpacing: '-0.02em' }}
          >
            {t('faq.title')}
          </h2>
        </div>
        <div className="min-w-0 border-t border-border">
          {items.map((item, i) => {
            const isOpen = open === i;
            return (
              <div key={item.q} className="border-b border-border">
                <button
                  type="button"
                  onClick={() => setOpen(isOpen ? null : i)}
                  className="flex w-full items-center justify-between gap-4 py-[1.1rem] text-left font-semibold text-foreground transition-colors hover:bg-secondary/40 dark:hover:bg-white/[0.04]"
                  style={{ fontSize: 'var(--text-body)' }}
                  aria-expanded={isOpen}
                >
                  <span className="pr-2">{item.q}</span>
                  <Plus
                    size={18}
                    className={`shrink-0 text-muted-foreground transition-transform duration-200 ${isOpen ? 'rotate-45' : ''}`}
                    aria-hidden
                  />
                </button>
                <div
                  className="grid transition-[grid-template-rows] duration-200 ease-out"
                  style={{ gridTemplateRows: isOpen ? '1fr' : '0fr' }}
                >
                  <div className="min-h-0 overflow-hidden">
                    <p
                      className="pb-[1.1rem] text-muted-foreground dark:text-neutral-400"
                      style={{ fontSize: 'var(--text-sm)', lineHeight: 'var(--leading-relaxed)' }}
                    >
                      {item.a}
                    </p>
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </section>
  );
}
