import { Routes, Route } from 'react-router';
import './i18n';
import { ThemeProvider } from './hooks/useTheme';
import HomePage from './pages/HomePage';
import ListaPage from './pages/ListaPage';
import SprintInquiryPage from './pages/SprintInquiryPage';
import CaseInternoIndexPage from './pages/CaseInternoIndexPage';
import CaseInternoDetailPage from './pages/CaseInternoDetailPage';

export default function App() {
  return (
    <ThemeProvider>
      <Routes>
        <Route path="/" element={<HomePage />} />
        <Route path="/caseinterno" element={<CaseInternoIndexPage />} />
        <Route path="/caseinterno/:slug" element={<CaseInternoDetailPage />} />
        <Route path="/sprint" element={<SprintInquiryPage />} />
        <Route path="/lista" element={<ListaPage />} />
      </Routes>
    </ThemeProvider>
  );
}
